- useMemo for derived data
- Debounced search input
- Pull-to-refresh with refreshControl

## Code Example

```javascript
import React, {useState, useMemo, useCallback} from 'react';
import {FlatList, TextInput, View, Text, RefreshControl} from 'react-native';

const ContactRow = React.memo(({c}) => (
  <View style={{padding:8}}>
    <Text>{c.firstName} {c.lastName}</Text>
    <Text>{c.phone}</Text>
  </View>
));

export default function Contacts({data}) {
  const [q, setQ] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  const filtered = useMemo(() => data.filter(c => {
    const n = (c.firstName + ' ' + c.lastName).toLowerCase();
    return n.includes(q.toLowerCase());
  }), [data, q]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    setTimeout(() => setRefreshing(false), 1000);
  }, []);

  return (
    <FlatList
      data={filtered}
      keyExtractor={item => item.id}
      renderItem={({item}) => <ContactRow c={item} />}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
    />
  );
}
```

